    return OpusGemmInstance(
        wm * wn * 64,
        bm,
        bn,
        bk,
        wm,
        wn,
        16,
        16,
        128,
        16,
        16,
        4,
        1,
        128,
        128,
        "a8w8_mxscale_bmm_bpreshuffle_compact",
        ["fp32_t"],
        WG_PER_CU=1,
        cachectl_a=0,
        cachectl_b=2 if nt else 0,
        num_slots=nb,
        early_b=early_b,
        name_root="opus_bmm",
        max_m=2047,
    )


