def _bpreshuffle_source_header(family, kind):
    suffix = family if family in ('support', 'host_contract') else f'{kind}_{family}'
    return f'opus_gemm_blockscale_mxscale_bpreshuffle_{suffix}_gfx950.cuh'


_BPRESHUFFLE_SOURCE_MODULES = [
    dict(family=family, kind=kind, schedule=schedule, level=level,
         header=_bpreshuffle_source_header(family, kind),
         macro=f'OPUS_BP_INCLUDE_{family.upper()}_{schedule}')
    for family, kind, level, schedules in _BPRESHUFFLE_SOURCE_LAYOUT
    for schedule in schedules
]
_BPRESHUFFLE_INCLUDE_BY_SOURCE = {
    (source['family'], source['schedule']): {
        key: source[key] for key in ('family', 'kind', 'schedule')
    }
    for source in _BPRESHUFFLE_SOURCE_MODULES
}

