def _bpreshuffle_jit_instance(
    kid, binding_index, launch_index, parameter_index, shape_index,
    workspace_index, tile_index, block_size, split_k, zero_init,
    kernel_calls, alignment_index, flags_index,
):
    family, schedule, launch_name, include_index = _BPRESHUFFLE_JIT_BINDINGS[binding_index]
    namespace = 'registers' if family == 'register' else family
    parameters = dict(_BPRESHUFFLE_JIT_PARAMETERS[parameter_index])
    bm, bn, bk = _BPRESHUFFLE_TILES[tile_index]
    entry = dict(
        kid=kid, pipeline=family, schedule=schedule,
        launch_func=f'opus_bpreshuffle_gfx950::{namespace}::schedule_{schedule}::{launch_name}',
        launch_parameters=list(_BPRESHUFFLE_LAUNCH_ARGUMENTS[launch_index]),
        includes=[dict(source) for source in _BPRESHUFFLE_INCLUDES[include_index]],
        parameters=parameters,
        supported_shapes=[list(shape) for shape in _BPRESHUFFLE_SHAPE_GROUPS[shape_index]],
        workspace_sizes={','.join(map(str, shape)): size
                         for shape, size in _BPRESHUFFLE_WORKSPACE_GROUPS[workspace_index]},
        workspace_zero_init=zero_init, split_k=split_k,
        expected_kernel_calls=kernel_calls,
        pointer_alignment=dict(_BPRESHUFFLE_POINTER_ALIGNMENTS[alignment_index]),
        block_size=block_size, tile=[bm, bn, bk],
        device_flags=list(_BPRESHUFFLE_DEVICE_FLAGS[flags_index]),
        **_BPRESHUFFLE_JIT_RANKS.get(kid, {}),
    )
    return OpusGemmInstance(
        BLOCK_SIZE=block_size, B_M=bm, B_N=bn, B_K=bk,
        T_M=parameters.get('wave_m', 1), T_N=parameters.get('wave_n', 4),
        W_M=16, W_N=16, W_K=128, VEC_A=16, VEC_B=16, VEC_C=4,
        GROUP_M=1, GROUP_N=128, GROUP_K=128,
        kernel_tag='a8w8_mxscale_gemm_bpreshuffle', output_dtypes=['bf16_t'],
        arch_prefix='gfx950', direct_only=True, scale_dtype='e8m0',
        pad_m=parameters.get('pad_m', True), bpreshuffle_split_k=split_k,
        bpreshuffle_entry=entry,
    )


