_BPRESHUFFLE_BMM_BY_SHAPE = {}
for _indices, _bmm_shapes in _BPRESHUFFLE_BMM_SHAPE_GROUPS:
    _choices = [list(_BPRESHUFFLE_BMM_CONFIGURATIONS[index]) for index in _indices]
    for _bmm_shape in _bmm_shapes:
        _BPRESHUFFLE_BMM_BY_SHAPE[_bmm_shape] = _choices


def bpreshuffle_pipeline(instance):
    if instance.bpreshuffle_entry is not None:
        return instance.bpreshuffle_entry['pipeline']
    if instance.bpreshuffle_co is not None:
        return instance.bpreshuffle_co['pipeline']
    return config_for(instance).pipeline


def bpreshuffle_implementation(kid):
    return _BPRESHUFFLE_PUBLIC_IMPLEMENTATIONS[kid]


def bpreshuffle_source_modules():
    return _BPRESHUFFLE_SOURCE_MODULES


def bpreshuffle_workspace_bytes(instance, m, n, k):
    if instance.bpreshuffle_entry is not None:
        return instance.bpreshuffle_entry['workspace_sizes'].get(','.join(map(str, (m, n, k))), 0)
    return 4 * instance.bpreshuffle_split_k * m * n if instance.bpreshuffle_split_k > 1 else 0


def bpreshuffle_bmm_candidates(m, n, k):
    return _BPRESHUFFLE_BMM_BY_SHAPE.get((m, n, k), ())

